// Package domain содержит сущности и ошибки предметной области.
package domain

// Weather — текущая погода в городе.
type Weather struct {
	City        string  // название из ответа провайдера
	Country     string  // ISO 3166-1 alpha-2, например "RU"
	TempC       float64 // температура, °C
	FeelsLikeC  float64 // ощущается как, °C
	Description string  // описание на русском, как прислал провайдер
	Humidity    int     // влажность, %
	WindSpeed   float64 // скорость ветра, м/с
	WindDeg     int     // направление ветра, градусы, 0 = север
}

package domain

import "errors"

// Ошибки предметной области. Сравниваются через errors.Is.
var (
	ErrInvalidCity         = errors.New("invalid city")
	ErrCityNotFound        = errors.New("city not found")
	ErrProviderAuth        = errors.New("weather provider auth failed")
	ErrRateLimited         = errors.New("weather provider rate limited")
	ErrProviderUnavailable = errors.New("weather provider unavailable")
)

// Package config читает переменные окружения и валидирует конфигурацию.
package config

import (
	"errors"
	"fmt"
	"log/slog"
	"os"
	"strings"
)

// Config — настроенные параметры бота.
type Config struct {
	TelegramBotToken   string
	OpenWeatherAPIKey  string
	TelegramBaseURL    string
	OpenWeatherBaseURL string
	LogLevel           slog.Level
}

// Load читает переменные окружения и возвращает все проблемы разом.
func Load() (Config, error) {
	var errs []error

	cfg := Config{
		TelegramBotToken:   os.Getenv("TELEGRAM_BOT_TOKEN"),
		OpenWeatherAPIKey:  os.Getenv("OPENWEATHER_API_KEY"),
		TelegramBaseURL:    "https://api.telegram.org",
		OpenWeatherBaseURL: "https://api.openweathermap.org",
		LogLevel:           slog.LevelInfo,
	}

	if cfg.TelegramBotToken == "" {
		errs = append(errs, errors.New("TELEGRAM_BOT_TOKEN is required"))
	}
	if cfg.OpenWeatherAPIKey == "" {
		errs = append(errs, errors.New("OPENWEATHER_API_KEY is required"))
	}

	if v := os.Getenv("TELEGRAM_BASE_URL"); v != "" {
		cfg.TelegramBaseURL = v
	}
	if v := os.Getenv("OPENWEATHER_BASE_URL"); v != "" {
		cfg.OpenWeatherBaseURL = v
	}

	if v := os.Getenv("LOG_LEVEL"); v != "" {
		level, err := parseLogLevel(v)
		if err != nil {
			errs = append(errs, err)
		} else {
			cfg.LogLevel = level
		}
	}

	return cfg, errors.Join(errs...)
}

func parseLogLevel(v string) (slog.Level, error) {
	switch strings.ToLower(v) {
	case "debug":
		return slog.LevelDebug, nil
	case "info":
		return slog.LevelInfo, nil
	case "warn":
		return slog.LevelWarn, nil
	case "error":
		return slog.LevelError, nil
	default:
		return slog.LevelInfo, fmt.Errorf("LOG_LEVEL must be one of debug/info/warn/error, got %q", v)
	}
}

package config

import (
	"errors"
	"log/slog"
	"testing"
)

func setEnv(t *testing.T, kv map[string]string) {
	t.Helper()
	for k, v := range kv {
		t.Setenv(k, v)
	}
}

func TestLoadDefaults(t *testing.T) {
	setEnv(t, map[string]string{
		"TELEGRAM_BOT_TOKEN": "tg-token",
		"OPENWEATHER_API_KEY": "owm-key",
	})
	cfg, err := Load()
	if err != nil {
		t.Fatalf("Load() err = %v", err)
	}
	if cfg.TelegramBaseURL != "https://api.telegram.org" {
		t.Errorf("TelegramBaseURL = %q", cfg.TelegramBaseURL)
	}
	if cfg.OpenWeatherBaseURL != "https://api.openweathermap.org" {
		t.Errorf("OpenWeatherBaseURL = %q", cfg.OpenWeatherBaseURL)
	}
	if cfg.LogLevel != slog.LevelInfo {
		t.Errorf("LogLevel = %v", cfg.LogLevel)
	}
}

func TestLoadMissingRequired(t *testing.T) {
	setEnv(t, map[string]string{
		"TELEGRAM_BOT_TOKEN": "",
		"OPENWEATHER_API_KEY": "",
	})
	_, err := Load()
	if err == nil {
		t.Fatal("Load() err = nil, want error")
	}
	var msg string
	for _, e := range []error{err} {
		msg = e.Error()
	}
	if !errors.Is(err, err) {
		t.Fatal("unreachable")
	}
	if !containsAll(t, msg, "TELEGRAM_BOT_TOKEN", "OPENWEATHER_API_KEY") {
		t.Errorf("err = %q, want both missing vars", msg)
	}
}

func containsAll(t *testing.T, s string, subs ...string) bool {
	t.Helper()
	for _, sub := range subs {
		if !stringsContains(s, sub) {
			return false
		}
	}
	return true
}

func stringsContains(s, sub string) bool {
	for i := 0; i+len(sub) <= len(s); i++ {
		if s[i:i+len(sub)] == sub {
			return true
		}
	}
	return false
}

func TestLoadCustomValues(t *testing.T) {
	setEnv(t, map[string]string{
		"TELEGRAM_BOT_TOKEN":   "tg-token",
		"OPENWEATHER_API_KEY":  "owm-key",
		"TELEGRAM_BASE_URL":    "http://127.0.0.1:8080",
		"OPENWEATHER_BASE_URL": "http://127.0.0.1:8081",
		"LOG_LEVEL":            "debug",
	})
	cfg, err := Load()
	if err != nil {
		t.Fatalf("Load() err = %v", err)
	}
	if cfg.TelegramBaseURL != "http://127.0.0.1:8080" {
		t.Errorf("TelegramBaseURL = %q", cfg.TelegramBaseURL)
	}
	if cfg.OpenWeatherBaseURL != "http://127.0.0.1:8081" {
		t.Errorf("OpenWeatherBaseURL = %q", cfg.OpenWeatherBaseURL)
	}
	if cfg.LogLevel != slog.LevelDebug {
		t.Errorf("LogLevel = %v", cfg.LogLevel)
	}
}

func TestLoadInvalidLogLevel(t *testing.T) {
	setEnv(t, map[string]string{
		"TELEGRAM_BOT_TOKEN":  "tg-token",
		"OPENWEATHER_API_KEY": "owm-key",
		"LOG_LEVEL":           "verbose",
	})
	_, err := Load()
	if err == nil {
		t.Fatal("Load() err = nil, want error for invalid LOG_LEVEL")
	}
}

