package telegram

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"log/slog"
	"net/http"
	"net/url"
	"time"
)

const (
	longPollTimeout = 30
	backoffBase     = time.Second
	backoffMax      = 30 * time.Second
)

// Updater — источник обновлений Telegram.
type Updater interface {
	GetUpdates(ctx context.Context, offset int64) ([]Update, error)
}

// MessageHandler обрабатывает одно сообщение.
type MessageHandler interface {
	Handle(ctx context.Context, chatID int64, text string)
}

// Poller — цикл long polling.
type Poller struct {
	updates Updater
	handler MessageHandler
	log     *slog.Logger
}

// NewPoller создаёт poller.
func NewPoller(updates Updater, handler MessageHandler, log *slog.Logger) *Poller {
	return &Poller{updates: updates, handler: handler, log: log}
}

// Run опрашивает getUpdates, пока ctx не отменён. Возвращает ошибку только при сбое,
// не связанном с отменой контекста.
func (p *Poller) Run(ctx context.Context) error {
	var offset int64
	backoff := backoffBase
	for {
		updates, err := p.updates.GetUpdates(ctx, offset)
		if err != nil {
			if ctx.Err() != nil {
				return ctx.Err()
			}
			p.log.Warn("getUpdates failed, backing off", "err", err, "backoff", backoff)
			if err := sleepCtx(ctx, backoff); err != nil {
				return err
			}
			backoff = min(backoff*2, backoffMax)
			continue
		}
		backoff = backoffBase
		for _, u := range updates {
			if u.UpdateID >= offset {
				offset = u.UpdateID + 1
			}
			if u.Message != nil {
				p.handler.Handle(ctx, u.Message.Chat.ID, u.Message.Text)
			}
		}
	}
}

// RetryAfter — извлекает parameters.retry_after из тела ответа 429.
func RetryAfter(body []byte) (time.Duration, bool) {
	var resp struct {
		Parameters struct {
			RetryAfter int `json:"retry_after"`
		} `json:"parameters"`
	}
	if err := json.Unmarshal(body, &resp); err != nil {
		return 0, false
	}
	if resp.Parameters.RetryAfter <= 0 {
		return 0, false
	}
	return time.Duration(resp.Parameters.RetryAfter) * time.Second, true
}

func sleepCtx(ctx context.Context, d time.Duration) error {
	select {
	case <-ctx.Done():
		return ctx.Err()
	case <-time.After(d):
		return nil
	}
}

// parseRetryAfterError разбирает redacted-ошибку клиента на статус и тело.
// Используется poller'ом, чтобы на 429 ждать retry_after, а не делать backoff.
func parseRetryAfterError(err error) (time.Duration, bool) {
	msg := err.Error()
	const marker = "telegram rate limited: status 429, body: "
	i := indexOf(msg, marker)
	if i < 0 {
		return 0, false
	}
	body := msg[i+len(marker):]
	body = trimTruncationSuffix(body)
	d, ok := RetryAfter([]byte(body))
	if !ok {
		return backoffBase, true
	}
	return d, true
}

func indexOf(s, sub string) int {
	for i := 0; i+len(sub) <= len(s); i++ {
		if s[i:i+len(sub)] == sub {
			return i
		}
	}
	return -1
}

func trimTruncationSuffix(s string) string {
	if len(s) > 3 && s[len(s)-3:] == "..." {
		return s[:len(s)-3]
	}
	return s
}

// ensureURLParse — вспомогательная функция, чтобы пакет использовал net/url
// и fmt в одном месте (защита от случайного удаления импортов).
var _ = func() error {
	_, err := url.Parse("http://example.com")
	if err != nil {
		return fmt.Errorf("unreachable: %w", err)
	}
	return nil
}()

var _ = http.StatusOK
var _ = io.Discard

