// Все тексты, которые видит пользователь.
const (
	msgStart       = "Привет! Я подскажу погоду. Просто напиши название города, например: Казань"
	msgHelp        = "Команды:\n/start — приветствие\n/help — эта справка\n/weather <город> — погода в городе\n\nПример: /weather Казань\nМожно просто написать название города без команды."
	msgEmptyCity   = "Напиши город после команды, например: /weather Пермь"
